"@H1|۸۷. سناریوی «سکوت»: فرسایش آرام",
"@P|در این سناریو، رفتار فعلی ادامه می‌یابد: «خبر خوب منتشر می‌شود»، «بحران تکذیب می‌شود» و «پرونده باز می‌ماند». و این «سناریو» «دراماتیک» نیست؛ «فرسایشی» است. و «فرسایش» در «عدد» دیده می‌شود، نه در «تیتر».",
"@P|**نشانهٔ اول: افت مقدار فروش.** در شش‌ماههٔ ۱۴۰۵، مقدار فروش داخلی ۲۷ درصد کاهش یافت (اس۱۳، اس۱۱). و «کاهش» می‌تواند «قیمت» یا «تقاضا» یا «سهم» باشد. و بدون «توضیح»، هر سه «احتمال» باقی می‌ماند و «بدترین» روایت می‌شود.",
"@P|**نشانهٔ دوم: کاهش اعتماد توزیع‌کننده.** «عامل فروش» وقتی «قیمت بازار» و «قیمت مصوب» فاصله بگیرد، «انگیزهٔ احتکار» پیدا می‌کند (بخش ۳۸). و «احتکار» «کمبود» می‌سازد و «کمبود» «بی‌اعتمادی» به «برند». و این «حلقه» در «سکوت» تقویت می‌شود.",
"@P|**نشانهٔ سوم: افزایش وزن «جوایز».** سازمانی که «خروجی» ندارد، «ورودی» را «بزرگ‌تر» می‌کند: «جایزهٔ بیشتر»، «مراسم بیشتر»، «حمایت بیشتر». و این «افزایش» در «کوتاه‌مدت» «تسکین» می‌دهد و در «بلندمدت» «فاصلهٔ ادعا و واقعیت» را «بزرگ‌تر» می‌کند.",
"@P|**نشانهٔ چهارم: خروج استعداد.** «مدیر ارتباطات» که «اختیار» ندارد، «می‌رود». و «رفتن» «حافظه» را می‌برد. و «حافظه» تنها «دارایی» است که «سند» می‌تواند «نگه دارد». و «سند» نیست (بخش ۴۹).",
"@P|**نشانهٔ پنجم: تسخیر روایت توسط دیگران.** در «سکوت»، «رسانه»، «نهاد» و «رقیب» «روایت» را می‌سازند. و «روایت» بدون «مقاومت» «تثبیت» می‌شود. و «تثبیت» پس از «دو سال» «برگشت‌ناپذیر» است، چون «کلیشه» شده است.",
"@P|**هزینهٔ فرسایش.** «هزینه» در «صورت مالی» دیده نمی‌شود، اما در «ارزش برند» دیده می‌شود. و «ارزش برند» در «ترازنامه» نیست. و «نبودن در ترازنامه» یعنی «مدیریت»، «هزینهٔ» آن را «نمی‌بیند». و «نمی‌بیند» یعنی «تصمیم نمی‌گیرد».",
"@P|**خوانش ما.** «سکوت» «ارزان‌ترین» سناریو در «کوتاه‌مدت» و «گران‌ترین» در «بلندمدت» است. و «ارزان» چون «تصمیم» نمی‌خواهد. و «گران» چون «سرمایه» را «بی‌صدا» می‌خورد.",
"@T|T85",
"@QC|جدول {N} — پنج نشانهٔ فرسایش و سنجهٔ آن",
"@H1|۸۸. سناریوی «بحران دوم»: آزمون واقعی",
"@P|اگر «بحران قیمت» در ۱۴۰۶ تکرار شود و «سندسازی» انجام نشده باشد، «آزمون دوم» سخت‌تر از «آزمون اول» خواهد بود. و دلیل، «کلیشه‌سازی» است: «بار اول» «اتهام» بود و «بار دوم» «الگو».",
"@P|**مکانیزم اول: «تکذیب» دیگر کار نمی‌کند.** در ۱۴۰۴، «تکذیب» یک «ادعا» بود که «رد» شد (اس۲۲). و در ۱۴۰۶، «تکذیب» «تکرار» یک «ادعای ردشده» است. و «تکرار» «بی‌اعتباری» را «تثبیت» می‌کند.",
"@P|**مکانیزم دوم: «رسانه» پیش از «شرکت» می‌داند.** در بحران اول، «رسانه» از «مردم» شنید. و در بحران دوم، «رسانه» از «تجربهٔ اول» می‌داند که «شرکت» دیر پاسخ می‌دهد. و «انتظار» «دیرپاسخی» باعث می‌شود «رسانه» «زودتر» منتشر کند.",
"@P|**مکانیزم سوم: «نهاد» محتاط‌تر می‌شود.** «سازمان حمایت» در ۱۴۰۴ گفت «مجوز صادر نشده» (اس۲۲). و در ۱۴۰۶، «نهاد» می‌تواند «سخت‌تر» عمل کند، چون «پروندهٔ دیوان» باز است (اس۲۱). و «سخت‌تر» یعنی «رسانه‌ای‌تر».",
"@P|**مکانیزم چهارم: «مصرف‌کننده» جایگزین پیدا می‌کند.** در «کمبود»، «مصرف‌کننده» «برند جایگزین» را «تجربه» می‌کند و «عادت» می‌شود. و «عادت» پس از «بحران» «برنمی‌گردد». و این «هزینهٔ پنهان» «کمبود» است.",
"@P|**مکانیزم پنجم: «سهامدار» می‌فروشد.** «ابهام» در «بورس» به «ریسک» تبدیل می‌شود و «ریسک» به «قیمت». و «قیمت سهم» «سنجهٔ نهایی» است — هرچند این گزارش «تحلیل قیمت» نمی‌کند. و «افت» «سرمایهٔ تأمین مالی» را «کم» می‌کند.",
"@P|**نکتهٔ درس.** «بحران دوم» همیشه «سخت‌تر» است، چون «حافظه» دارد. و «حافظه» با «سند» «مدیریت» می‌شود و با «سکوت» «تقویت». و «ایرانول» در «نقطهٔ» انتخاب «سند یا سکوت» است.",
"@P|**خوانش ما.** «بحران دوم» «آزمون واقعی» است و «نمرهٔ» آن در «سه روز اول» نوشته می‌شود. و «سه روز» با «یک رویهٔ مکتوب» قابل «مدیریت» است. و «رویه» «همین حالا» قابل «نوشتن» است.",
"@T|T86",
"@QC|جدول {N} — پنج مکانیزم تشدید در بحران دوم",
"@H1|۸۹. سناریوی «تغییر مالکیت»: پیام در ابهام",
"@P|«تاپیکو» سهامدار اصلی ایرانول است و «شستا» در سطح بالاتر (اس۱۴، اس۱۵). و در سال‌های اخیر، «بازار سرمایه» شاهد «تغییر ترکیب سهامداران» در شرکت‌های دولتی بوده است. و «تغییر مالکیت» یک «بحران ارتباطی خاموش» است.",
"@P|**نکتهٔ اول: «مالکیت» پیام را عوض می‌کند.** اگر «سهامدار» عوض شود، «سیاست ارتباطی» هم می‌تواند عوض شود. و «کارکنان» و «مشتری» نگران «تداوم» می‌شوند. و «نگرانی» بدون «اطلاعیه» به «شایعه» تبدیل می‌شود.",
"@P|**نکتهٔ دوم: «بورس» سازوکار افشا دارد.** «اطلاعیهٔ تغییر سهامدار» در «کدال» منتشر می‌شود. و «انتشار» «رسمی» است. اما «تفسیر» («چه تغییری در راهبرد می‌شود») «رسمی» نیست. و «تفسیر» همان چیزی است که «کارکنان» می‌خواهند.",
"@P|**نکتهٔ سوم: «نام تجاری» ممکن است بماند یا عوض شود.** «ایرانول» یک «برند ملی» است و «تغییر نام» «هزینهٔ ارتباطی» بزرگی دارد. و «حفظ نام» یک «پیام» است: «تداوم». و «پیام» باید «صریح» باشد، نه «ضمنی».",
"@P|**نکتهٔ چهارم: «مسئولیت اجتماعی» در تغییر مالکیت «بازبینی» می‌شود.** «پروژه‌های مسئولیت اجتماعی» ممکن است «بودجه» را از دست بدهند. و «کارکنان آبادان» که به «حضور شرکت» وابسته‌اند، «نگران» می‌شوند. و «نگرانی» باید «پاسخ» بگیرد.",
"@P|**نکتهٔ پنجم: «پروندهٔ دیوان» می‌تواند «تسریع» شود.** «سهامدار جدید» ممکن است «پرونده» را «ببندد» یا «بازتر» کند. و هر دو «خبر» است. و «خبر» باید «توضیح» شود، نه «رها».",
"@P|**نکتهٔ ششم: «ارتباطات» در این سناریو «دفاعی» نیست، «تثبیتی» است.** «پیام» این است: «کسب‌وکار ادامه دارد، قراردادها معتبر است، کارکنان می‌مانند». و «سه جمله» باید «پیش از» «شایعه» گفته شود. و «پیش» یعنی «آماده بودن».",
"@P|**خوانش ما.** «تغییر مالکیت» یک «احتمال» است که «آمادگی» می‌خواهد. و «آمادگی» یک «بستهٔ اطلاع‌رسانی» است: «پرسش و پاسخ کارکنان، اطلاعیهٔ مشتری و پیام تأمین‌کننده». و «بسته» در «یک روز» قابل «تدوین» است.",
"@T|T87",
"@QC|جدول {N} — شش نکتهٔ تغییر مالکیت و اقدام لازم",
"@H1|۹۰. ریسک ارتباطی: پنجرهٔ زمانی و هزینهٔ تأخیر",
"@P|«ریسک ارتباطی» با «ریسک عملیاتی» تفاوت دارد: «عملیاتی» با «سرمایه» کاهش می‌یابد و «ارتباطی» با «زمان». و «زمان» تنها «منبعی» است که «بازگشت» ندارد. و در پروندهٔ ایرانول، «پنجرهٔ زمانی» «بسته» یا «در حال بسته شدن» است.",
"@P|**پنجرهٔ اول: «بعد از بحران» (بسته).** پس از «بحران قیمت ۱۴۰۴»، «پنجرهٔ» توضیح «طبیعی» بسته شد. و هر «توضیح» در ۱۴۰۶ «دیرهنگام» خوانده می‌شود، مگر با «سند تازه» بیاید. و «سند تازه» یعنی «گزارش» یا «نتیجهٔ بررسی».",
"@P|**پنجرهٔ دوم: «پیش از بحران بعدی» (باز).** هر «سندسازی» پیش از «بحران بعدی» «سرمایه» می‌سازد. و «سرمایه» در «بحران» «خرج» می‌شود. و «پنجره» تا «بحران بعدی» «باز» است — و «بحران بعدی» «تاریخ» ندارد.",
"@P|**پنجرهٔ سوم: «تغییر مدیرعامل» (باز، کوتاه).** «۱۰۰ روز اول» مدیرعامل جدید، «پنجرهٔ» «بازتعریف» است. و میرزاپور از ۱۴۰۵/۰۷/۳۰ «مدیرعامل» است (اس۱۹). و «۱۰۰ روز» تا «دی ۱۴۰۵» است. و «پنجره» در حال «بسته شدن» است.",
"@P|**هزینهٔ تأخیر: عدد یک.** «هر ماه تأخیر» در «سندسازی» یعنی «یک بحران بدون رویه». و «بحران» در صنعت «سالانه» است (بخش ۳۹). و «احتمال» «یک بحران در سال» «بالا» است. و «بالا» یعنی «تأخیر» «ریسک» است، نه «صرفه‌جویی».",
